INSERT INTO language_levels(language_id, cefr_code) SELECT l.id, c.code FROM languages l, cefr_levels c WHERE l.code = 'mr' AND c.code IN ('A1', 'A2');
INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'A1', 'greetings', 'Greetings', 'Greet your neighbours and settle into your building, in Marathi.', 'You''ve just moved into a flat in Andheri West. Joshi kaka, your building society''s secretary, comes to say hello.', 'Use “tumhi” (you, polite) with elders and neighbours, and “tu” only with friends. “Kasa kay?” is the friendly Mumbai hello.', 1, 'published', datetime('now'), datetime('now'), 1);
INSERT INTO lesson_topics(lesson_id, topic_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'greetings'), (SELECT id FROM topics WHERE slug = 'greetings'));
INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'A1', 'transport', 'Transport', 'Take the local train, and get taxis and autos to use the meter.', 'You need to get from Andheri to Churchgate in the morning rush.', 'Ask a taxi “…la yenar ka?” (will you come to …?): that''s how Mumbaikars ask. Check the board for F (fast) or S (slow) before you board a local.', 2, 'published', datetime('now'), datetime('now'), 1);
INSERT INTO lesson_topics(lesson_id, topic_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'transport'), (SELECT id FROM topics WHERE slug = 'transport'));
INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'A1', 'food', 'Food', 'Order street food the Mumbai way, in Marathi.', 'Evening snack at a vada pav stall outside Dadar station.', '“Dya” (please give) is the polite way to order. Ask for “suki chatni”, the dry garlic chutney, and order chai as “ek cutting”.', 3, 'published', datetime('now'), datetime('now'), 1);
INSERT INTO lesson_topics(lesson_id, topic_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'food'), (SELECT id FROM topics WHERE slug = 'food'));
INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'A1', 'shopping', 'Shopping', 'Bargain politely at a Marathi market.', 'You''re at the Ranade Road market in Dadar, looking for a kurta.', 'Shopkeepers at Dadar''s markets warm up quickly when you bargain in Marathi. Start at about half and settle in the middle, with a smile.', 4, 'published', datetime('now'), datetime('now'), 1);
INSERT INTO lesson_topics(lesson_id, topic_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'shopping'), (SELECT id FROM topics WHERE slug = 'shopping'));
INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'A1', 'directions', 'Directions', 'Find your way around stations and streets.', 'You came out of Andheri station on the wrong side.', 'Most stations have an East and a West side, so ask “Eastla ki Westla?” before you walk. “Pul” is the footbridge over the tracks.', 5, 'published', datetime('now'), datetime('now'), 1);
INSERT INTO lesson_topics(lesson_id, topic_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'directions'), (SELECT id FROM topics WHERE slug = 'directions'));
INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'A1', 'college', 'College & Work', 'Settle in with colleagues and classmates, in Marathi.', 'Your first day at an office in BKC (Bandra Kurla Complex).', 'Colleagues often switch between Marathi, Hindi and English mid-sentence. “Mast” means great, and you''ll hear it all day.', 6, 'published', datetime('now'), datetime('now'), 1);
INSERT INTO lesson_topics(lesson_id, topic_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'college'), (SELECT id FROM topics WHERE slug = 'college'));
INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'A1', 'smalltalk', 'Real Conversation', 'Put everything together in a natural conversation.', 'Cutting chai on Marine Drive with Aditya, your new flatmate, as the monsoon begins.', 'With friends, Marathi turns casual: “Kay re?” (what''s up?), “jhakaas” (awesome), “bindhast” (no worries). Keep “tumhi” for elders.', 7, 'published', datetime('now'), datetime('now'), 1);
INSERT INTO lesson_topics(lesson_id, topic_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'smalltalk'), (SELECT id FROM topics WHERE slug = 'smalltalk'));
INSERT INTO lesson_age_groups(lesson_id, age_group_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'college'), (SELECT id FROM age_groups WHERE code = 'teen'));
INSERT INTO lesson_age_groups(lesson_id, age_group_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'college'), (SELECT id FROM age_groups WHERE code = 'adult'));
