INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'mr'), 'A1', 'polite-requests', 1);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'polite-requests'), (SELECT id FROM languages WHERE code = 'en'), 'Polite requests: verbs ending in -a', 'Marathi''s polite way to ask uses the “tumhi” form of the verb, which ends in -a: “dya” (please give), “sanga” (please tell), “ghala” (please put in), “vala” (please turn). With friends the short “tu” form is fine: “de”, “sang”.');
