INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'question-ka'), (SELECT id FROM languages WHERE code = 'en'), 'Yes/no questions with “ka?”', 'Add “ka?” at the end of a sentence to make it a yes/no question: “Dadarla thaambel” (it will stop at Dadar) becomes “Dadarla thaambel ka?” (will it stop at Dadar?).');
