INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'place-la'), (SELECT id FROM languages WHERE code = 'en'), 'Going somewhere: add “-la”', '“-la” joined to a place means “to”: “Dadarla” (to Dadar), “Juhula” (to Juhu), “Westla” (to the west side). Some places change their ending first (Bandra → Bandryala).');
